html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro dots(n) -%}{% for i in range(n) %}&hellip;{% endfor %}{%- endmacro -%}
<style>
.lpl-letter { font-family: Cambria, Georgia, serif; font-size: 12.5px; color: #000; line-height: 1.55; }
.lpl-letter p { margin: 0 0 12px; }
.lpl-letter .addr { font-weight: bold; margin: 0; }
.lpl-letter h4 { font-size: 12.5px; font-weight: bold; text-decoration: underline; margin: 14px 0 12px; }
.lpl-letter .logo { text-align: right; margin: 0 0 18px; }
.lpl-letter .sign-off { margin: 22px 0 0; }
.lpl-letter .who { font-weight: bold; text-transform: uppercase; margin: 0; }
.lpl-letter ol, .lpl-letter ul { margin: 0 0 12px 18px; padding: 0; }
.lpl-letter li { margin: 0 0 4px; }
.lpl-form table.grid { width: 100%; border-collapse: collapse; margin: 0 0 14px; }
.lpl-form table.grid th, .lpl-form table.grid td { border: 1px solid #000; padding: 5px 7px; font-size: 12px;
  text-align: left; vertical-align: top; }
.lpl-form table.grid th { background: #f2f2f2; font-weight: bold; }
.lpl-form .ref { width: 100%; border-collapse: collapse; margin: 0 0 14px; }
.lpl-form .ref td { border: 1px solid #000; padding: 4px 6px; font-size: 11px; }
.lpl-form h3 { font-size: 13px; text-align: center; text-transform: uppercase; margin: 10px 0 14px; }
.lpl-comment { border: 1px solid #000; padding: 8px 10px; margin: 0 0 12px; }
.lpl-comment .head { font-weight: bold; margin: 0 0 6px; }
.lpl-comment .body { min-height: 42px; white-space: pre-wrap; }
</style>
<div class="lpl-form lpl-letter">
{%- if doc.change_type != "Phone Number" %}
<p style="color:#8a1c1c">This print is the Phone Number Change Request; this one changes the {{ v(doc.change_type) }}.</p>
{%- else %}
{%- set ref = "LPL/HR/33" %}{% set issued = "11/10/2025" %}{% set title = "PHONE NUMBER CHANGE REQUEST FORM" %}
<table class="ref"><tr>
<td rowspan="2" style="width:34%"><b>LUUKA PLASTICS LIMITED</b></td>
<td>Doc Ref. No: {{ ref }}</td><td>Initial Issue Date {{ issued }}</td></tr>
<tr><td>Revision Date: NIL</td><td>Revision No. 0</td></tr>
<tr><td colspan="3" style="text-align:center"><b>{{ title }}</b></td></tr></table>

<p>Name {{ v(doc.employee_name) }}</p>
<p>Title {{ v(doc.designation) }}</p>
<p>Date {{ day(doc.request_date) }}</p>
<p>The Human Resource Manager<br>Luuka Plastics Limited</p>
<p><b>Subject: Request for Change of Phone Number</b></p>
<p>Dear Human Resource,</p>
<p>I hope this message finds you well. I am writing to kindly request to change my wages phone number details.</p>
<p>Please update my records from phone number details captured below;</p>
<table class="grid">
<tr><th style="width:30%">Phone Number</th><td>{{ v(doc.current_phone_number) }}</td></tr>
<tr><th>Registered Names</th><td>{{ v(doc.current_registered_names) }}</td></tr>
</table>
<p>To the phone number details captured below so that all my future wage payments are made to this phone number;</p>
<table class="grid">
<tr><th style="width:30%">Phone Number</th><td>{{ v(doc.new_phone_number) }}</td></tr>
<tr><th>Registered Names</th><td>{{ v(doc.new_registered_names) }}</td></tr>
</table>
<p>I appreciate your assistance in this matter.</p>
<p>Yours sincerely,</p>
<p>Name {{ v(doc.employee_name) }} &hellip;&hellip;&hellip;&hellip;&hellip;</p>
<p>Signature &hellip;&hellip;&hellip;&hellip;&hellip;&hellip;&hellip; Date {{ day(doc.employee_signed_on) }}</p>
{%- if doc.status == "Approved" %}
<p style="margin-top:16px"><b>Effected by</b> {{ v(frappe.db.get_value("User", doc.approved_by, "full_name")
  if doc.approved_by else "") }} on {{ day(doc.approved_on) }}</p>
{%- endif %}
{%- endif %}
</div>
